import { ANEX_ADDITIONS } from "./anex-additions";

export type CuratedToolReference = {
  id: string;
  brand: string;
  brandSlug: string;
  model: string;
  namePt: string;
  japanese: string;
  task:
    | "precision"
    | "fastening"
    | "sockets"
    | "grip"
    | "cutting"
    | "hvac"
    | "power"
    | "electronics"
    | "ev";
  categoryPt: string;
  notePt: string;
  badge: string;
  referenceUrl: string;
  imageUrl?: string;
  imageAlt?: string;
  imageSourceLabel?: string;
  imageCaption?: string;
  kitContents?: string[];
  evidencePt?: string;
  specPt?: string;
  featured?: boolean;
  limitationsPt?: string;
  manufacturedIn?: string;
  catalogViewerPage?: number;
  storyPt?: string;
  compareGroup?: string;
  officialCode?: string;
  /** Simbologia da casa — normas e certificação. "EN IEC 60900" basta para 1000 V
   *  (híbrido incluído); ASTM F1505 é o equivalente americano aceito. */
  normPt?: string;
  /** Certificação/página oficial da marca com a marcação (short link válido). */
  certificationUrl?: string;
  /** Tipo de aço com dureza quando declarada (ex.: "Cr-Mo-V · HRC 62,5", "S2"). */
  steelPt?: string;
  /** Tratamento/revestimento (ex.: "têmpera por indução", "fosfato de manganês"). */
  treatmentPt?: string;
  /** Tipo de corte para cortadores (ex.: "fio piano Ø2,5 mm · VVF 2,0×3"). */
  cutTypePt?: string;
  /** Escala da casa 0-5: 0 = fora de gama, 5 = muito bom. */
  qualityDots?: number;
};

